(() => {
const near=(x,v,t=.025)=>Math.abs(x-v)<=t;
const value=(root,id)=>Number(root.querySelector('#'+id)?.value);
const fmt=n=>(Math.abs(Number(n))<1e-10?0:Number(n)).toFixed(3);
window.FIELD_MISSIONS={
function:{title:'Transporta la curva',goal:'Construye y=2(x−1)². Su mínimo está en x=1 y su altura en x=0 es 2.',clue:'Selecciona Cuadrática. La escala controla a y la traslación controla b.',test(root){const a=value(root,'fa'),b=value(root,'fb'),mode=root.querySelector('[data-mode].active')?.dataset.mode;return{pass:mode==='quadratic'&&near(a,2)&&near(b,1),readout:`a=${fmt(a)} · b=${fmt(b)}`}}},
derivative:{title:'Captura el límite',goal:'Encuentra una tangente de pendiente −2 y acerca la secante a menos de 0.05 de esa pendiente.',clue:'Para f(x)=x², la tangente tiene pendiente 2x y la secante 2x+h.',test(root){const x=value(root,'dx'),h=value(root,'dh');return{pass:near(2*x,-2,.01)&&h<=.05,readout:`Tangente ${fmt(2*x)} · separación ${fmt(h)}`}}},
integral:{title:'Resuelve la acumulación',goal:'Integra hasta b=1.5 y lleva el error relativo de la suma de Riemann por debajo de 2%.',clue:'Para la suma por extremos derechos, el error relativo es 3/(2n)+1/(2n²).',test(root){const b=value(root,'ib'),n=value(root,'in'),err=1.5/n+.5/(n*n);return{pass:near(b,1.5,.01)&&err<.02,readout:`b=${fmt(b)} · error ${(100*err).toFixed(2)}%`}}},
matrix:{title:'Invierte la orientación',goal:'Intercambia los dos vectores base: e₁ debe ir a (0,1) y e₂ a (1,0). El área conserva magnitud 1 y cambia orientación.',clue:'Los destinos de e₁ y e₂ son las columnas de la matriz.',test(root){const a=value(root,'ma'),b=value(root,'mb'),c=value(root,'mc'),d=value(root,'md');return{pass:near(a,0)&&near(b,1)&&near(c,1)&&near(d,0),readout:`det=${fmt(a*d-b*c)} · columnas (${a},${c}), (${b},${d})`}}},
bayes:{title:'Actualiza hasta 4:1',goal:'Configura prior 1/2 y sensibilidad 0.8. Ajusta el falso positivo hasta obtener posterior 0.8: odds de 4 a 1.',clue:'Con prior simétrico, posterior=t/(t+f).',test(root){const p=value(root,'bp'),t=value(root,'bt'),f=value(root,'bf'),post=p*t/(p*t+(1-p)*f);return{pass:near(p,.5,.001)&&near(t,.8,.001)&&near(post,.8,.005),readout:`Posterior=${fmt(post)} · odds=${fmt(post/(1-post))}`}}},
distribution:{title:'Diseña una creencia precisa',goal:'Construye una gaussiana con media 1 y precisión 4.',clue:'Precisión=1/σ². No confundas desviación con varianza.',test(root){const m=value(root,'gm'),s=value(root,'gs');return{pass:near(m,1)&&near(1/(s*s),4,.01),readout:`μ=${fmt(m)} · precisión=${fmt(1/(s*s))}`}}},
gradient:{title:'Desciende a la cuenca',goal:'Llega a E<0.005 usando al menos cuatro pasos de descenso, con tamaño η<0.5.',clue:'Cerca del mínimo el gradiente se reduce. Un η demasiado grande amplifica y.',test(root){const x=value(root,'gx'),y=value(root,'gy'),l=value(root,'gl'),steps=Number(root.dataset.steps||0),E=x*x+2*y*y;return{pass:E<.005&&l<.5&&steps>=4,readout:`E=${fmt(E)} · pasos=${steps} · η=${l}`}}},
entropy:{title:'Iguala sin eliminar incertidumbre',goal:'Haz que p mantenga H(p)>0.68 nats y q lo describa con KL(p∥q)<0.005 nats.',clue:'Alta incertidumbre y baja divergencia son compatibles. p cercano a 1/2 y q cercano a p.',test(root){const p=value(root,'hp'),q=value(root,'hq'),h=MATH_ENGINE.entropy(p),kl=MATH_ENGINE.kl(p,q);return{pass:h>.68&&kl<.005,readout:`H=${fmt(h)} · KL=${fmt(kl)}`}}},
dynamics:{title:'Estabiliza una fluctuación',goal:'Desde x₀=1.5, logra |E[x(8)]|<0.01 y una varianza estacionaria entre 0.08 y 0.12.',clue:'Aumenta k para restaurar. Compensa el ruido con σ²/(2k).',test(root){const k=value(root,'dk'),s=value(root,'dn'),x=value(root,'d0'),mean=x*Math.exp(-8*k),variance=s*s/(2*k);return{pass:near(x,1.5,.01)&&k>0&&Math.abs(mean)<.01&&variance>=.08&&variance<=.12,readout:`Media=${fmt(mean)} · varianza=${fmt(variance)}`}}},
variational:{title:'Cierra la brecha variacional',goal:'Ajusta q hasta KL(q∥posterior)<0.001 nats. Observa cómo F se acerca a la sorpresa.',clue:'El posterior objetivo tiene μ=0.6 y σ=0.7; igualar sus parámetros cierra la brecha.',test(root){const m=value(root,'vm'),s=value(root,'vs'),kl=Math.log(.7/s)+(s*s+(m-.6)**2)/(.98)-.5;return{pass:kl<.001,readout:`KL=${fmt(kl)} · F=${fmt(kl-Math.log(.2))}`}}},
markov:{title:'Propaga y vuelve a inferir',goal:'Con α=0.15 y β=0.35, realiza al menos tres predicciones y tres actualizaciones de evidencia hasta p(L)>0.94.',clue:'La predicción empuja a una distribución estacionaria; cada señal L acumula evidencia.',test(root){const a=value(root,'ka'),b=value(root,'kb'),p=Number(root.dataset.belief||0);return{pass:near(a,.15,.001)&&near(b,.35,.001)&&p>.94&&Number(root.dataset.predictions)>=3&&Number(root.dataset.observations)>=3,readout:`p(L)=${fmt(p)} · columnas normalizadas`}}},
policy:{title:'Descubre el valor de explorar',goal:'Con creencia y preferencias simétricas (p=c=0.5), ajusta el sensor para que la exploración aporte más de 0.3 nats.',clue:'I=ln2−H(r) en este caso. Mejor sensor → menor ambigüedad → mayor valor epistémico.',test(root){const p=value(root,'pp'),c=value(root,'pc'),r=value(root,'pr'),ig=Math.log(2)-MATH_ENGINE.entropy(r);return{pass:near(p,.5,.001)&&near(c,.5,.001)&&ig>.3,readout:`I=${fmt(ig)} · G(explorar)=${fmt(MATH_ENGINE.entropy(r))}`}}},
agent:{title:'Compra información y actúa',goal:'En un episodio, escanea entre una y tres veces; encuentra el recurso con confianza de al menos 0.85 en el lado elegido.',clue:'Una señal da posterior 0.85. Si señales contradictorias bajan la confianza, considera otra lectura o un nuevo episodio.',test(root){return{pass:root.dataset.agentSolved==='true',readout:root.dataset.agentSolved==='true'?'Inferencia + acción verificadas.':'El episodio aún no demuestra ese resultado. El sensor tiene ruido.'}}}
};
})();
